//
// MLPerf Tiny keyword spotting (DS-CNN) / visual wake words (MobileNetV1)
// inference + fused Grad-CAM on GeMMX, generated by data/mobile.py (real
// reference int8 models, real Speech Commands / COCO inputs):
//  - DMA core: places input rows into the padded C8HW8 buffer (2-D DMA,
//    C-byte pixels into 8-byte channel slots), streams each launch's weight /
//    bias tile from L3 one step ahead into two buffers, refills borders with
//    -128 when a buffer changes shape, and resets the columns W..Wi-1 a layer
//    wrote past the map width (one 2-D DMA per channel tile);
//  - core 0: one GeMMX launch per step (generated delta CSR writes); picks
//    the predicted class, writes alpha (its FC row) and the zero-point bias,
//    and finishes Grad-CAM (ReLU + Q15 normalisation);
//  - logits, last feature map and class activation map are compared byte
//    for byte with the emulator.

#include <stdint.h>

#include "snrt.h"             // write_csr, used by the generated cfg_* in data.h
#include "snax-gemmx-lib.h"
#include "data.h"

enum { OP_FILL = 1, OP_ROWS, OP_DMAS, OP_ALPHA, OP_CAM };
enum { PH_INPUT = 0, PH_FILL = 4, PH_GRADCAM = 6 };

static int pred = -1;

static void op_alpha(uint8_t *l1, const op_t *op) {
    const int8_t *lg = (const int8_t *)(l1 + op->a);
    int8_t best = -128;
    for (int i = 0; i < PROG_NCLS; i++) {               // logits: row 0 of the blocks
        int8_t v = lg[(i / 8) * 64 + (i % 8)];
        if (v > best || pred < 0) { best = v; pred = i; }
    }
    // alpha = FC row of pred: 8 bytes per K tile from the FC B blocks in TCDM
    // (layout Nt, Kt, col, k) into column 0 of the Grad-CAM B blocks
    const uint32_t *src = (const uint32_t *)(l1 + op->d + (pred / 8) * PROG_KT * 64 + (pred % 8) * 8);
    uint32_t *dst = (uint32_t *)(l1 + op->b);
    for (int k = 0; k < PROG_KT; k++) {
        dst[k * 16] = src[k * 16];
        dst[k * 16 + 1] = src[k * 16 + 1];
    }
    const int32_t c = ((const int32_t *)(l1 + op->e))[pred];   // -zp * sum(alpha)
    int32_t *ct = (int32_t *)(l1 + op->c);
    for (int i = 0; i < 64; i++) ct[i] = c;
}

static void op_cam(uint8_t *l1, const op_t *op) {
    // cam[y*w + x] = column 0 of D32 block (y*mw + x/8), row x%8; ReLU + Q15
    const int32_t *d = (const int32_t *)(l1 + op->a);
    int32_t *cam = (int32_t *)(l1 + op->b);
    const int h = op->c, w = op->d, mw = op->e;
    int32_t mx = 0;
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++) {
            int32_t v = d[(y * mw + x / 8) * 64 + (x % 8) * 8];
            v = v < 0 ? 0 : v;
            cam[y * w + x] = v;
            if (v > mx) mx = v;
        }
    uint32_t inv = mx > 0 ? (1u << 31) / (uint32_t)mx : 0;
    for (int i = 0; i < h * w; i++) cam[i] = (int32_t)(((uint64_t)(uint32_t)cam[i] * inv) >> 16);
}

// Runs one op on both cores (each does its part), ends with a barrier.
static void run_op(uint8_t *l1, const op_t *op, int core0, int dm) {
    if (op->type == OP_FILL) {
        if (dm) snrt_dma_memset(l1 + op->a, 0x80, op->b);
    } else if (op->type == OP_ROWS) {
        if (dm) {
            const int cin = op->c >> 16, npx = op->c & 0xFFFF;
            for (int r = 0; r < op->d; r++)
                snrt_dma_start_2d(l1 + op->a + r * op->e, prog_in + op->b + r * cin * npx, cin, 8,
                                  cin, npx);
        }
    } else if (op->type == OP_DMAS) {
        if (dm)
            for (int i = op->a; i < op->b; i++) {
                const dma2d_t *q = &prog_dmas[i];
                snrt_dma_start_2d(l1 + q->dst, l1 + q->src, q->size, q->dst_stride, q->src_stride,
                                  q->repeat);
            }
    } else if (op->type == OP_ALPHA) {
        if (core0) op_alpha(l1, op);
    } else if (op->type == OP_CAM) {
        if (core0) op_cam(l1, op);
    }
    if (dm) snrt_dma_wait_all();
    snrt_cluster_hw_barrier();
}

static int op_phase(const op_t *op) {
    if (op->type == OP_ROWS) return PH_INPUT;
    if (op->type == OP_ALPHA || op->type == OP_CAM) return PH_GRADCAM;
    return PH_FILL;
}

int main() {
    uint8_t *l1 = (uint8_t *)snrt_l1_next();
    const int core0 = snrt_global_core_idx() == 0;
    const int dm = snrt_is_dm_core();
    if (dm) {
        snrt_dma_start_1d(l1, prog_image, PROG_IMAGE_BYTES);
        snrt_dma_wait_all();
    }
    snrt_cluster_hw_barrier();

    uint32_t phase_cyc[N_PHASES] = {0}, cfg = 0, run = 0, ops_dma = 0, ops_core = 0;
    uint32_t t_start = snrt_mcycle();
    if (dm) {
        snrt_dma_start_1d(l1 + prog_blob_dst[PROG_FIRST_BLOB],
                          prog_params + prog_blob_off[PROG_FIRST_BLOB],
                          prog_blob_len[PROG_FIRST_BLOB]);
        snrt_dma_wait_all();
    }
    snrt_cluster_hw_barrier();
    if (core0) phase_cyc[PH_INPUT] += snrt_mcycle() - t_start;

    for (int s = 0; s < PROG_N_STEPS; s++) {
        const mstep_t *st = &prog_steps[s];
        for (int o = st->pre0; o < st->pre1; o++) {
            uint32_t a = snrt_mcycle();
            run_op(l1, &prog_ops[o], core0, dm);
            if (core0) {
                uint32_t d = snrt_mcycle() - a;
                phase_cyc[op_phase(&prog_ops[o])] += d;
                if (prog_ops[o].type >= OP_ALPHA) ops_core += d; else ops_dma += d;
            }
        }
        if (dm && st->prefetch >= 0)
            snrt_dma_start_1d(l1 + prog_blob_dst[st->prefetch],
                              prog_params + prog_blob_off[st->prefetch],
                              prog_blob_len[st->prefetch]);
        uint32_t a = snrt_mcycle();
        if (core0 && st->launch >= 0) {
            cfg_fns[st->launch]((uint32_t)l1);
            uint32_t b1 = snrt_mcycle();
            set_gemmx_streamer_start();
            set_gemmx_start();
            wait_gemmx_and_streamer();
            cfg += b1 - a;
            run += snrt_mcycle() - b1;
        }
        if (dm) snrt_dma_wait_all();
        snrt_cluster_hw_barrier();
        if (core0) phase_cyc[st->phase] += snrt_mcycle() - a;
        for (int o = st->pre1; o < st->post1; o++) {
            uint32_t b = snrt_mcycle();
            run_op(l1, &prog_ops[o], core0, dm);
            if (core0) {
                uint32_t d = snrt_mcycle() - b;
                phase_cyc[op_phase(&prog_ops[o])] += d;
                if (prog_ops[o].type >= OP_ALPHA) ops_core += d; else ops_dma += d;
            }
        }
    }
    uint32_t t_end = snrt_mcycle();
    snrt_cluster_hw_barrier();

    uint32_t err = 0;
    if (core0) {
        printf("[TOTAL] %u cycles, %d steps: config=%u run=%u dma-ops=%u core-ops=%u, "
               "predicted class %d\n",
               t_end - t_start, PROG_N_STEPS, cfg, run, ops_dma, ops_core, pred);
        for (int p = 0; p < N_PHASES; p++)
            if (phase_cyc[p]) printf("  %-8s %u\n", prog_phase_names[p], phase_cyc[p]);
        for (int c = 0; c < PROG_N_CHECKS; c++) {
            const uint8_t *got = l1 + prog_check_off[c];
            const uint8_t *exp = prog_expected + prog_check_pos[c];
            uint32_t e = 0;
            for (int j = 0; j < prog_check_len[c]; j++) e += got[j] != exp[j];
            printf("check %-7s %s (%u/%d bytes differ)\n", prog_check_names[c],
                   e ? "FAIL" : "OK", e, prog_check_len[c]);
            err += e;
        }
    }
    snrt_cluster_hw_barrier();
    return err;
}
